const runsAfter = `import { and, desc, eq, lt } from "drizzle-orm"
import { db } from "@/db"
import { runs } from "@/db/schema"

export type RunStatus = "queued" | "running" | "passed" | "failed"

export interface Run {
  id: string
  name: string
  status: RunStatus
  branch: string
  commitSha: string
  durationMs: number | null
  createdAt: Date
}

export interface RunsPage {
  runs: Run[]
  /** Pass back to getRuns for the next page. Null on the last page. */
  nextCursor: string | null
}

const PAGE_SIZE = 20

export async function getRuns(
  projectId: string,
  { cursor, limit = PAGE_SIZE }: { cursor?: string; limit?: number } = {},
): Promise<RunsPage> {
  const rows = await db
    .select()
    .from(runs)
    .where(
      cursor
        ? and(eq(runs.projectId, projectId), lt(runs.createdAt, new Date(cursor)))
        : eq(runs.projectId, projectId),
    )
    .orderBy(desc(runs.createdAt))
    .limit(limit + 1)

  const hasMore = rows.length > limit
  const page = hasMore ? rows.slice(0, limit) : rows
  const last = page[page.length - 1]
  return { runs: page, nextCursor: hasMore && last ? last.createdAt.toISOString() : null }
}

export async function getRun(projectId: string, id: string): Promise<Run | undefined> {
  const [row] = await db
    .select()
    .from(runs)
    .where(and(eq(runs.projectId, projectId), eq(runs.id, id)))
    .limit(1)
  return row
}

export async function countRuns(projectId: string): Promise<number> {
  const rows = await db.select({ id: runs.id }).from(runs).where(eq(runs.projectId, projectId))
  return rows.length
}

export function formatDuration(ms: number | null) {
  if (ms === null) return "Running"
  if (ms < 1000) return \`\${ms} ms\`
  if (ms < 60_000) return \`\${(ms / 1000).toFixed(1)} s\`
  return \`\${Math.floor(ms / 60_000)} m \${Math.round((ms % 60_000) / 1000)} s\`
}
`

