const loadMore = `"use client"

import { useState, useTransition } from "react"
import type { Run } from "@/lib/runs"
import { RunRow } from "./run-row"

export function LoadMore({ projectId, cursor }: { projectId: string; cursor: string }) {
  const [runs, setRuns] = useState<Run[]>([])
  const [next, setNext] = useState<string | null>(cursor)
  const [pending, startTransition] = useTransition()

  function load() {
    if (!next) return
    startTransition(async () => {
      const res = await fetch(\`/api/projects/\${projectId}/runs?cursor=\${encodeURIComponent(next)}\`)
      const page: { runs: Run[]; nextCursor: string | null } = await res.json()
      setRuns((current) => [...current, ...page.runs])
      setNext(page.nextCursor)
    })
  }

  return (
    <>
      <ul className="divide-y">
        {runs.map((run) => (
          <RunRow key={run.id} run={run} />
        ))}
      </ul>
      {next ? (
        <button type="button" onClick={load} disabled={pending} className="mt-4 text-sm">
          {pending ? "Loading runs…" : "Load 20 more"}
